def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    in_escape = False
    index = 0
    while index < len(line):
        ch = line[index]
        if not in_quotes:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        elif in_quotes:
            if ch == '"':
                in_quotes = False
                in_escape = False
            elif ch == ',':
                current.append(ch)
            elif ch == '\\':
                in_escape = True
            else:
                if in_escape:
                    current.append(ch)
                    in_escape = False
                else:
                    current.append(ch)
        index += 1
    fields.append(''.join(current))
    return fields
```

This revised implementation correctly handles the cases where a quote is escaped with a backslash and where a field contains a comma.

